(()=>{'use strict';const experience=v=>v==='helper'?'Franklin helper':'GTA V iOS launcher';const time=v=>{const d=new Date(String(v).replace(' ','T')+'Z');return Number.isNaN(d.getTime())?String(v):new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(d)+' WIB'};const reference=v=>'GTA-'+String(v).slice(0,8).toUpperCase();const normalize=r=>({reference:reference(r.id),reportId:r.id,submittedAtUTC:String(r.created_at).replace(' ','T')+'Z',submittedAtJakarta:time(r.created_at),experience:experience(r.target),type:r.kind==='issue'?'Issue':'Feedback',rating:Number(r.rating),summary:r.title,description:r.message,reproductionSteps:r.steps||'',operatingSystem:r.os||'Not specified',osVersion:r.version||'Not specified',device:r.device||'Not specified',appBuild:r.build||'Not specified',status:r.status||'received'});
const columns={reference:'Reference',reportId:'Report ID',submittedAtUTC:'Submitted at (UTC)',submittedAtJakarta:'Submitted at (Asia/Jakarta)',experience:'Experience',type:'Type',rating:'Rating (1–5)',summary:'Summary',description:'Description',reproductionSteps:'Steps to reproduce',operatingSystem:'Operating system',osVersion:'OS version',device:'Device',appBuild:'App / launcher build',status:'Status'};
function cell(v){let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function csv(rows){return '\uFEFF'+[Object.values(columns),...rows.map(r=>Object.keys(columns).map(k=>normalize(r)[k]))].map(r=>r.map(cell).join(',')).join('\r\n')}
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function json(rows,summary,filters){return JSON.stringify({report:'GTA V iOS Community / Feedback & Issues',schemaVersion:1,generatedAt:new Date().toISOString(),displayTimeZone:'Asia/Jakarta',filters,exportedReports:rows.length,projectSummary:summary,ratingMethod:'Latest rating per browser and experience. Rating counts can differ from report counts.',reports:rows.map(normalize)},null,2)}
function html(rows,summary,filters){const rating=(summary.ratings||[]).map(r=>`${experience(r.target)}: ${Number(r.average).toFixed(2)}/5 (${r.count} ratings)`).join(' · ')||'No community ratings yet';return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GTA V iOS Community — Feedback report</title><style>body{font:15px/1.65 system-ui,sans-serif;color:#202820;background:#fff;max-width:960px;margin:40px auto;padding:0 28px}header{border-bottom:3px solid #4e6b3d;padding-bottom:24px}h1{font-size:32px;line-height:1.2;margin:10px 0}h2{font-size:21px;margin:5px 0 18px}h3{font-size:14px;margin:24px 0 6px;color:#4e6b3d}p{white-space:pre-wrap;overflow-wrap:anywhere}small,dt{color:#5f675f}.summary{background:#f1f4ee;border-radius:12px;padding:20px;margin:24px 0}.record{border-bottom:1px solid #cdd4ca;padding:26px 0;break-inside:avoid}dl{display:grid;grid-template-columns:140px 1fr;gap:6px 20px;font-size:13px}dd{margin:0;overflow-wrap:anywhere}.tag{font-size:12px;color:#4e6b3d;font-weight:700}footer{font-size:12px;color:#5f675f;margin-top:30px}@media print{body{margin:0;padding:0;font-size:11pt}.summary{background:#fff;border:1px solid #ccc}.record{break-inside:auto}h2,h3{break-after:avoid}}</style><header><small>PRIVATE PROJECT REPORT · GTA V IOS COMMUNITY</small><h1>Feedback & Issues</h1><p>Generated ${escape(new Date().toLocaleString('en-GB',{timeZone:'Asia/Jakarta'}))} WIB · ${rows.length} matching reports</p><small>Filters: ${escape(Object.entries(filters).filter(([,v])=>v).map(([k,v])=>k+': '+v).join(' · ')||'All reports')}</small></header><section class="summary"><strong>Project snapshot</strong><p>${Number(summary.reports||0)} total reports · ${Number(summary.issues||0)} issues · ${Number(summary.feedback||0)} feedback submissions</p><p>${escape(rating)}</p><small>Ratings count the latest rating per browser and experience. This summary covers the project; individual reports below follow your filters.</small></section>${rows.length?rows.map(raw=>{const r=normalize(raw);return `<article class="record"><span class="tag">${escape(r.reference)} · ${escape(r.type)} · ${r.rating}/5</span><h2>${escape(r.summary)}</h2><dl>${[['Experience',r.experience],['Submitted',r.submittedAtJakarta],['Operating system',r.operatingSystem+' '+r.osVersion],['Device',r.device],['App / build',r.appBuild],['Status',r.status],['Full report ID',r.reportId]].map(([k,v])=>`<dt>${k}</dt><dd>${escape(v)}</dd>`).join('')}</dl><h3>Description</h3><p>${escape(r.description)}</p>${r.reproductionSteps?`<h3>Steps to reproduce</h3><p>${escape(r.reproductionSteps)}</p>`:''}</article>`}).join(''):'<p>No reports match these filters.</p>'}<footer>Private feedback shared with project administrators. Store and share this export carefully. Open this file in a browser to read or print it.</footer></html>`}
window.ProjectFeedbackExport={csv,json,html,normalize,time,experience,reference};})();
